/**
 * Cache de canvas fora da tela para as cutscenes renderizadas.
 */
const cutsceneCanvasCache = new Map<string, HTMLCanvasElement>();

/**
 * Cria ou recupera um HTMLCanvasElement fora da tela com o frame da cutscene renderizado.
 */
export function getCutsceneCanvas(
  cutsceneId: string,
  frameIndex: number = 0
): HTMLCanvasElement | null {
  const data = CUTSCENE_RAW_DATA[cutsceneId];
  if (!data) return null;

  const validFrame = Math.abs(frameIndex) % data.frames.length;
  const cacheKey = `${cutsceneId}_${validFrame}`;

  const cached = cutsceneCanvasCache.get(cacheKey);
  if (cached) return cached;

  const canvas = document.createElement('canvas');
  canvas.width = data.width;
  canvas.height = data.height;
  const ctx = canvas.getContext('2d');
  if (!ctx) return null;

  ctx.imageSmoothingEnabled = false;

  const matrix = data.frames[validFrame];
  for (let y = 0; y < data.height; y++) {
    const row = matrix[y] || '';
    for (let x = 0; x < data.width; x++) {
      const char = row[x] || '.';
      const color = data.palette[char];
      if (color && color !== 'transparent') {
        ctx.fillStyle = color;
        ctx.fillRect(x, y, 1, 1);
      }
    }
  }

  cutsceneCanvasCache.set(cacheKey, canvas);
  return canvas;
}

/**
 * Retorna os metadados de uma cutscene pelo seu identificador.
 */
export function getCutsceneData(cutsceneId: string): CutsceneGraphicData | null {
  return CUTSCENE_RAW_DATA[cutsceneId] || null;
}
